-- Exact dyadic known answers; integer formulas documented in oracle map. NOT_RUN.
DO $test$
BEGIN
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('0x0.0p+0','UTF8') THEN RAISE EXCEPTION 'exact binary64 midpoint'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('-0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('-0x0.0p+0','UTF8') THEN RAISE EXCEPTION 'exact binary64 midpoint'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('0x1.0000000000000p-1022','UTF8') THEN RAISE EXCEPTION 'exact binary64 midpoint'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('-0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('-0x1.0000000000000p-1022','UTF8') THEN RAISE EXCEPTION 'exact binary64 midpoint'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('.0','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('0x1.fffffffffffffp+1023','UTF8') THEN RAISE EXCEPTION 'exact binary64 midpoint'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('.0','UTF8')) IS NOT NULL THEN RAISE EXCEPTION 'max finite carry overflow'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('-.0','UTF8')) IS NOT NULL THEN RAISE EXCEPTION 'max finite carry overflow'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('1e-000001','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('0x1.999999999999ap-4','UTF8') THEN RAISE EXCEPTION 'six exponent digits'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('1e-0000001','UTF8')) IS NOT NULL THEN RAISE EXCEPTION 'seven exponent digits'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('0.'||pg_catalog.repeat('0',4095),'UTF8')) IS DISTINCT FROM pg_catalog.convert_to('0x0.0p+0','UTF8') THEN RAISE EXCEPTION '4096 mantissa digits'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('0.'||pg_catalog.repeat('0',4096),'UTF8')) IS NOT NULL THEN RAISE EXCEPTION '4097 mantissa digits'; END IF;
END
$test$;

-- Exact adjacent dyadics on either side of midpoint, both signs. NOT_RUN.
DO $test$
BEGIN
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('0x0.0p+0','UTF8') THEN RAISE EXCEPTION 'adjacent exact dyadic'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('-0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('-0x0.0p+0','UTF8') THEN RAISE EXCEPTION 'adjacent exact dyadic'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('0x0.0000000000001p-1022','UTF8') THEN RAISE EXCEPTION 'adjacent exact dyadic'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('-0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('-0x0.0000000000001p-1022','UTF8') THEN RAISE EXCEPTION 'adjacent exact dyadic'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('0x0.fffffffffffffp-1022','UTF8') THEN RAISE EXCEPTION 'adjacent exact dyadic'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('-0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('-0x0.fffffffffffffp-1022','UTF8') THEN RAISE EXCEPTION 'adjacent exact dyadic'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('0x1.0000000000000p-1022','UTF8') THEN RAISE EXCEPTION 'adjacent exact dyadic'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('-0.','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('-0x1.0000000000000p-1022','UTF8') THEN RAISE EXCEPTION 'adjacent exact dyadic'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('.0','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('0x1.fffffffffffffp+1023','UTF8') THEN RAISE EXCEPTION 'adjacent exact dyadic'; END IF;
    IF modkit_events._decimal_float_hex(pg_catalog.convert_to('-.0','UTF8')) IS DISTINCT FROM pg_catalog.convert_to('-0x1.fffffffffffffp+1023','UTF8') THEN RAISE EXCEPTION 'adjacent exact dyadic'; END IF;
END
$test$;
